INSERT INTO #Apps (AppCode, DbName, NameEn, NameAr, Description, ReaderLogin, ReaderPassword) VALUES
(N'PERSONNEL', N'WabiBankPersonnelDB', N'Personnel and Attendance', N'شؤون الموظفين والحضور', N'Wabi Bank HRMS: divisions, departments, branches and sections, positions and grades, employees, movements, leave, daily attendance for 2025, and the bank''s systems with each employee''s user id and access (the source of every identifier the other systems reuse).', N'wbpersonnel_reader', N'WbPersonnel#Reader#2026'),
(N'CORE-BANKING', N'WabiBankCoreBankingDB', N'Core Banking', N'النظام المصرفي الأساسي', N'Customers (CIF), KYC, accounts and every posting of 2025, cheque clearing (outward and inward), remittances, teller tills, fixed deposits, loans with schedules and repayments, and month-end balances. Postings carry the staff UserId and the posting unit.', N'wbcore_reader', N'WbCore#Reader#2026'),
(N'FINANCE', N'WabiBankFinanceDB', N'Finance', N'المالية', N'Chart of accounts, cost centres (departments and sections), FY2025 original and revised budgets, budget transfers, purchase requisitions and orders, goods receipts, vendor invoices, payments, fixed assets and the general ledger.', N'wbfinance_reader', N'WbFinance#Reader#2026'),
(N'DIGITAL-BANKING', N'WabiBankDigitalDB', N'Digital Banking', N'الخدمات المصرفية الرقمية', N'Internet and mobile banking for Core Banking customers: profiles, devices, sign-ins, beneficiaries, channel transfers (posted in Core Banking), Contact Centre service requests and profile actions, 2025.', N'wbdigital_reader', N'WbDigital#Reader#2026'),
(N'IT-HELPDESK', N'WabiBankITDB', N'IT Help Desk', N'مكتب خدمات تقنية المعلومات', N'IT service management with two modules, Requests (service catalogue, approvals, tasks) and Incidents (priority, SLA, activities), plus services, configuration items and assignment groups, 2025.', N'wbit_reader', N'WbIt#Reader#2026');
INSERT INTO #Sections SELECT SectionCode, DepartmentCode, SectionName, SectionNameAr FROM ' + QUOTENAME(@PersonnelDb) + N'.dbo.Sections;
INSERT INTO #Relations
INSERT INTO #ObjectDocs VALUES
(N'PERSONNEL', N'Divisions', N'Divisions', N'القطاعات', N'The bank''s divisions under the CEO (Retail, Wholesale, Operations and Technology, Risk, Finance, HR, Marketing, CEO Office), each headed by an executive.'),
(N'PERSONNEL', N'Locations', N'Locations', N'المواقع', N'Head Office (Dubai) and the six banking branches with emirate, address, opening date and number of counters.'),
(N'PERSONNEL', N'Departments', N'Departments and branches', N'الإدارات والفروع', N'Department-level units: the 15 Head Office departments and the 6 banking branches (DepartmentType Branch). Codes are shared by every Wabi Bank system and are the finance cost centres.'),
(N'PERSONNEL', N'Sections', N'Sections', N'الأقسام', N'Sub-units of departments and branches. Every branch has Customer Service, Teller and Cash, Personal Banking and Sales, and Branch Operations sections.'),
(N'PERSONNEL', N'JobGrades', N'Job grades', N'الدرجات الوظيفية', N'Grades G1 (Associate) to G10 (Executive) with the monthly salary band in AED.'),
(N'PERSONNEL', N'Positions', N'Positions', N'المسميات الوظيفية', N'Job titles with grade; branch positions are shared by all branches (DepartmentCode empty).'),
(N'PERSONNEL', N'Countries', N'Countries and nationalities', N'الدول والجنسيات', N'Nationalities of employees.'),
(N'PERSONNEL', N'PublicHolidays', N'UAE public holidays 2025', N'العطل الرسمية 2025', N'Days when Head Office and branches are closed (the Contact Centre and security work).'),
(N'PERSONNEL', N'Shifts', N'Shifts', N'الورديات', N'Working hours: Head Office, branches, Contact Centre (three shifts, seven days) and security rota.'),
(N'PERSONNEL', N'Employees', N'Employees', N'الموظفون', N'Everyone employed in 2025 (including leavers): names EN/AR, nationality, Emirates ID, hire and termination dates, division, department or branch, section, position, grade, line manager, shift, work e-mail and the UserId used in every system (empty for staff without system access).'),
(N'PERSONNEL', N'EmployeeMovements', N'Transfers and promotions', N'التنقلات والترقيات', N'Movements in 2025 with effective date and the unit, position and grade before and after.'),
(N'PERSONNEL', N'LeaveTypes', N'Leave types', N'أنواع الإجازات', N'Annual, sick, emergency and maternity leave with entitlement.'),
(N'PERSONNEL', N'LeaveRequests', N'Leave requests', N'طلبات الإجازات', N'Leave requests with dates, working days, status and who decided (the line manager''s UserId).'),
(N'PERSONNEL', N'AttendanceRecords', N'Daily attendance', N'الحضور اليومي', N'One row per employee per rostered working day of 2025: Present, Late, Absent or OnLeave, check-in and check-out, late and overtime minutes, and the unit the employee belonged to that day.'),
(N'PERSONNEL', N'Systems', N'Systems', N'الأنظمة', N'The bank''s systems that use the shared identities: CBS, HRMS, FIN, DIGITAL, ITSM.'),
(N'PERSONNEL', N'SystemUsers', N'System users', N'مستخدمو الأنظمة', N'One login (UserId) per employee with system access, used in every system, plus service accounts (batch, clearing, digital channel, monitoring).'),
(N'PERSONNEL', N'UserSystemAccess', N'System access', N'صلاحيات الأنظمة', N'Which systems each UserId may use, with the role, approval limit, granted date and revoked date.'),
(N'CORE-BANKING', N'Branches', N'Branches', N'الفروع', N'The six banking branches (Head Office is not a branch). BranchCode is the department code shared with every Wabi Bank system.'),
(N'CORE-BANKING', N'Units', N'Posting units', N'وحدات الترحيل', N'Units that post transactions: the branches and the Head Office departments OPS (central operations and batch), DCC (digital channel), CBD and TRY.'),
(N'CORE-BANKING', N'Users', N'Core banking users', N'مستخدمو النظام المصرفي', N'Users with core-banking access in 2025 (same UserId, employee number and units as Personnel) and the service accounts.'),
(N'CORE-BANKING', N'BusinessCalendar', N'Business calendar 2025', N'التقويم 2025', N'Every day of 2025 with weekday, weekend flag (Saturday, Sunday) and UAE public holidays; branches open Monday to Friday.'),
(N'CORE-BANKING', N'Currencies', N'Currencies', N'العملات', N'Currencies held or transferred.'),
(N'CORE-BANKING', N'FxRates', N'Exchange rates', N'أسعار الصرف', N'Daily rate to AED per currency (USD, SAR, JOD pegged).'),
(N'CORE-BANKING', N'Products', N'Products', N'المنتجات', N'Current, savings and business account products with monthly fee and interest rate.'),
(N'CORE-BANKING', N'TransactionCodes', N'Transaction codes', N'رموز المعاملات', N'Posting codes: salary, ATM, card, teller cash, cheques, transfers, digital, fees, interest, loans, fixed deposits.'),
(N'CORE-BANKING', N'Customers', N'Customers', N'العملاء', N'Customer master (CIF): individuals (including staff, whose salary is paid into Wabi Bank), SMEs and corporates, segment, nationality, risk rating, home branch, relationship manager (employee number) and the user who onboarded them.'),
(N'CORE-BANKING', N'KycDocuments', N'KYC documents', N'وثائق اعرف عميلك', N'Emirates ID, passport and trade licence of each customer with issue and expiry dates; expired documents need renewal.'),
(N'CORE-BANKING', N'Accounts', N'Accounts', N'الحسابات', N'Accounts with IBAN, product, currency, home branch, status (Active, Dormant, Closed), who opened and approved them, opening balance (1 January 2025 or the opening date) and ledger balance (31 December 2025 or closure).'),
(N'CORE-BANKING', N'FixedDeposits', N'Fixed deposits', N'الودائع لأجل', N'Term deposits with principal, rate, tenor, start and maturity, funding account and the user who booked them.'),
(N'CORE-BANKING', N'Transactions', N'Transactions', N'المعاملات', N'Every posting of 2025: account, code, debit or credit, amount (and AED), posting time, channel, posting unit, the user who posted and approved it, reversals and the balance after the posting.'),
(N'CORE-BANKING', N'TellerTills', N'Teller tills', N'صناديق الصرافين', N'Each teller''s cash position per business day: opening cash, cash in, cash out, expected and counted closing cash and the difference.'),
(N'CORE-BANKING', N'MonthEndBalances', N'Month-end balances', N'أرصدة نهاية الشهر', N'Balance of every open account at each month end of 2025 (account currency and AED).'),
(N'CORE-BANKING', N'ClearingSessions', N'Clearing sessions', N'جلسات المقاصة', N'Two UAE cheque clearing sessions per business day.'),
(N'CORE-BANKING', N'ChequeReturnReasons', N'Cheque return reasons', N'أسباب إرجاع الشيكات', N'Why a cheque was returned unpaid.'),
(N'CORE-BANKING', N'ChequeBooks', N'Cheque books', N'دفاتر الشيكات', N'Cheque books issued on current accounts with the leaf range.'),
(N'CORE-BANKING', N'OutwardCheques', N'Cheques deposited (outward clearing)', N'الشيكات المودعة', N'Cheques drawn on other banks that customers deposited at a branch, captured by branch operations, cleared or returned.'),
(N'CORE-BANKING', N'InwardCheques', N'Cheques presented (inward clearing)', N'الشيكات المقدمة', N'Cheques written by Wabi Bank customers and presented by other banks, paid or returned (insufficient funds, signature, stopped ...).'),
(N'CORE-BANKING', N'OutwardTransfers', N'Outward transfers', N'الحوالات الصادرة', N'Local (UAEFTS) and SWIFT transfers initiated at branches and processed by Central Operations (maker and checker), with sanctions screening and charges.'),
(N'CORE-BANKING', N'InwardTransfers', N'Inward transfers', N'الحوالات الواردة', N'Local and SWIFT transfers received for customers.'),
(N'CORE-BANKING', N'LoanProducts', N'Loan products', N'منتجات القروض', N'Personal, auto, home and SME loans.'),
(N'CORE-BANKING', N'LoanApplications', N'Loan applications 2025', N'طلبات القروض 2025', N'Applications sourced by branch sales or SME relationship managers (employee number), decided by Credit Risk users within their approval limits.'),
(N'CORE-BANKING', N'Loans', N'Loans', N'القروض', N'The loan book: principal, rate, tenor, start and maturity, monthly instalment, repayment account and who disbursed and approved the disbursement.'),
(N'CORE-BANKING', N'LoanSchedules', N'Loan schedules', N'جداول سداد القروض', N'Monthly instalments falling due in 2025 with principal, interest and outstanding balance.'),
(N'CORE-BANKING', N'LoanRepayments', N'Loan repayments', N'سداد القروض', N'Instalments paid on time, late or not paid in 2025.'),
(N'CORE-BANKING', N'MonthEndArrears', N'Month-end arrears', N'المتأخرات في نهاية الشهر', N'Overdue instalments per loan at each month end with days past due and bucket (Current, 1-30, 31-60, 61-90, 90+).'),
(N'CORE-BANKING', N'MonthEndLoanBalances', N'Month-end loan balances', N'أرصدة القروض في نهاية الشهر', N'Outstanding principal of every active loan at each month end of 2025 (after the instalments due by then), with customer, product and branch. Use it for loan book size by branch, product or month.'),
(N'CORE-BANKING', N'vw_TransactionsByStaff', N'Transactions with posting staff', N'المعاملات مع الموظف المرحِّل', N'Transactions with the posting user''s employee number, department and section (from Users).'),
(N'CORE-BANKING', N'vw_OutwardChequesByStaff', N'Deposited cheques with capturing staff', N'الشيكات المودعة مع الموظف', N'Outward cheques with the capturing user''s employee number, department and section.'),
(N'CORE-BANKING', N'vw_OutwardTransfersByStaff', N'Outward transfers with approving staff', N'الحوالات الصادرة مع الموظف المعتمِد', N'Outward transfers with the approving (checker) user''s employee number, department and section.'),
(N'CORE-BANKING', N'vw_TransactionsLive', N'Transactions (live demo window)', N'المعاملات (نافذة العرض المباشر)', N'December 2025 transactions shifted so that 31 December 2025 is today (Asia/Dubai), for Monitoring Rules demos.'),
(N'CORE-BANKING', N'vw_InwardChequesLive', N'Presented cheques (live demo window)', N'الشيكات المقدمة (نافذة العرض المباشر)', N'December 2025 presented cheques shifted so that 31 December 2025 is today (Asia/Dubai).'),
(N'FINANCE', N'Users', N'Finance users', N'مستخدمو النظام المالي', N'Everyone who held a role in the finance system during 2025 (copy of Personnel access): user id, employee number, unit, FIN role, approval limit before VAT, status and access dates. SYS_FIN_IF is the interface service account.'),
(N'FINANCE', N'ChartOfAccounts', N'Chart of accounts', N'دليل الحسابات', N'General-ledger accounts with type (Asset, Liability, Equity, Income, Expense), category (Staff costs, Premises, IT, Marketing, Professional fees, Depreciation ...) and whether the account is budgeted (operating expenses).'),
(N'FINANCE', N'CostCentres', N'Cost centres', N'مراكز التكلفة', N'One cost centre per department or branch (CostCentreType Department) and per section (Section); the code equals the department or section code, with division, location and the unit head on 31 December 2025.'),
(N'FINANCE', N'FiscalPeriods', N'Fiscal periods', N'الفترات المالية', N'The twelve 2025 accounting months; January to November closed by the Financial Controller, December still open.'),
(N'FINANCE', N'BudgetVersions', N'Budget versions', N'نسخ الموازنة', N'FY2025-ORIGINAL (approved December 2024) and FY2025-REVISED (Q2 re-forecast approved June 2025, current from July; its January-June lines equal the original).'),
(N'FINANCE', N'BudgetLines', N'Budget lines', N'بنود الموازنة', N'Monthly operating-expense budget per version, cost centre and GL account (AED). Staff costs and premises are budgeted on department cost centres, purchases and depreciation where they are incurred. Compare with JournalLines on Expense accounts.'),
(N'FINANCE', N'BudgetTransfers', N'Budget transfers', N'مناقلات الموازنة', N'Requests by department heads to move budget between cost centres or accounts of their department, approved or rejected by the Budget Manager; recorded separately, not included in BudgetLines.'),
(N'FINANCE', N'Vendors', N'Vendors', N'الموردون', N'Suppliers of goods and services: category, rating (A preferred, B acceptable, C under review), UAE tax registration number, bank account (IBAN), payment terms and status.'),
(N'FINANCE', N'PurchaseRequisitions', N'Purchase requisitions', N'طلبات الشراء', N'Purchase requests of 2025 by department and section: requester, creator, spend category, estimated amount before VAT, status (Draft, Submitted, Approved, Rejected, Converted) and the approver (department head up to AED 50,000, CFO up to 2,000,000, CEO above).'),
(N'FINANCE', N'PurchaseRequisitionLines', N'Purchase requisition lines', N'بنود طلبات الشراء', N'Items or services requested, quantity, estimated unit price and amount, and the GL account to be charged.'),
(N'FINANCE', N'PurchaseOrders', N'Purchase orders', N'أوامر الشراء', N'Orders issued by Procurement buyers from approved requisitions: vendor, unit, buyer, approver (Procurement Manager up to AED 100,000 before VAT, CFO up to 2,000,000, CEO above), order and expected delivery dates, subtotal, 5 % VAT, total and status.'),
(N'FINANCE', N'PurchaseOrderLines', N'Purchase order lines', N'بنود أوامر الشراء', N'Ordered items with quantity, unit price, amount before VAT, GL account and quantity received.'),
(N'FINANCE', N'GoodsReceipts', N'Goods receipts', N'استلام البضائع والخدمات', N'Deliveries and service acceptances recorded by the ordering unit (or a Head Office facilities coordinator): receipt date, receiver, delivery sequence and value received before VAT.'),
(N'FINANCE', N'VendorInvoices', N'Vendor invoices', N'فواتير الموردين', N'Vendor invoices entered by Accounts Payable: invoice and due dates, net, VAT and total, three-way match result (Matched, PriceVariance, QuantityVariance, NoReceipt) and status (Open, OnHold, Paid).'),
(N'FINANCE', N'Payments', N'Vendor payments', N'مدفوعات الموردين', N'Bank transfers to vendors: prepared by a payables officer (maker) and released by the payables supervisor (checker) on the payment date.'),
(N'FINANCE', N'JournalEntries', N'Journal entries', N'القيود اليومية', N'General-ledger journals of 2025: manual accruals and reclassifications (accountant and Financial Controller) and interface batches posted by SYS_FIN_IF (payroll, depreciation, premises and ATM costs, core banking income, vendor invoices and payments).'),
(N'FINANCE', N'JournalLines', N'Journal lines', N'بنود القيود', N'Debit and credit lines per GL account and cost centre (department and section). Actual cost = DebitAmount - CreditAmount on Expense accounts; balance-sheet lines have no cost centre.'),
(N'FINANCE', N'FixedAssets', N'Fixed assets', N'الأصول الثابتة', N'Asset register: IT equipment, furniture, vehicles, ATMs and branch equipment, leasehold improvements, with cost centre, custodian, acquisition date and cost, useful life, accumulated depreciation and net book value at 31 December 2025.'),
(N'DIGITAL-BANKING', N'Branches', N'Branches', N'الفروع', N'The six banking branches (codes shared with every Wabi Bank system).'),
(N'DIGITAL-BANKING', N'Users', N'Digital banking staff users', N'مستخدمو الخدمات الرقمية', N'Staff with digital-banking access in 2025 (Contact Centre, Digital Channels, branch customer service for enrolment, fraud investigators) and the channel service account; same UserId and units as Personnel.'),
(N'DIGITAL-BANKING', N'DigitalProfiles', N'Digital profiles', N'الملفات الرقمية', N'Internet and mobile banking profiles of individual Core Banking customers (CIF): username, enrolment date and channel (branch staff or self-service), home branch and status.'),
(N'DIGITAL-BANKING', N'Devices', N'Devices', N'الأجهزة', N'Devices registered to each profile: platform, model, first and last seen, trusted flag.'),
(N'DIGITAL-BANKING', N'SignIns', N'Sign-ins', N'عمليات تسجيل الدخول', N'Every sign-in attempt in 2025: profile, device, time, channel (mobile or web), IP country, success or the failure reason.'),
(N'DIGITAL-BANKING', N'Beneficiaries', N'Beneficiaries', N'المستفيدون', N'Payees added by customers: within Wabi Bank, local (other UAE banks) or international, with the cooling-off activation time.'),
(N'DIGITAL-BANKING', N'ChannelTransfers', N'Channel transfers', N'التحويلات الرقمية', N'Transfers made in the app or online banking in 2025 with amount, payee, status and the Core Banking reference of the posting.'),
(N'DIGITAL-BANKING', N'ServiceRequests', N'Contact Centre service requests', N'طلبات خدمة مركز الاتصال', N'Customer requests (card block, limit change, device reset, password reset, complaint, dispute) handled by Contact Centre agents, with SLA and resolution.'),
(N'DIGITAL-BANKING', N'ProfileActions', N'Profile actions', N'إجراءات الملفات الرقمية', N'Locks, unlocks, device resets and limit changes made by staff on customers'' profiles.'),
(N'DIGITAL-BANKING', N'vw_SignInsLive', N'Sign-ins (live demo window)', N'تسجيلات الدخول (نافذة العرض المباشر)', N'December 2025 sign-ins shifted so that 31 December 2025 is today (Asia/Dubai), for Monitoring Rules demos.'),
(N'DIGITAL-BANKING', N'vw_ChannelTransfersLive', N'Channel transfers (live demo window)', N'التحويلات الرقمية (نافذة العرض المباشر)', N'December 2025 channel transfers shifted so that 31 December 2025 is today (Asia/Dubai).'),
(N'IT-HELPDESK', N'Locations', N'Locations', N'المواقع', N'Head Office and the six banking branches (location codes shared with Personnel) with emirate, address, opening date and teller counters.'),
(N'IT-HELPDESK', N'EmployeeDirectory', N'Employee directory', N'دليل الموظفين', N'Every Wabi Bank employee of 2025, leavers included, as synchronised from Personnel: employee number, names, department, section and location (current at year end, or at termination), work email, login (UserId; none for drivers, messengers and guards), active flag, hire and termination dates.'),
(N'IT-HELPDESK', N'Users', N'Help-desk users', N'مستخدمو مكتب الخدمة', N'Logins with IT Help Desk access during 2025 and their role: Requester (self-service), Agent (IT staff), GroupLead (IT section heads), ServiceDeskManager, and the SYS_MONITOR service account that opens monitoring incidents; access granted and revoked dates.'),
(N'IT-HELPDESK', N'AssignmentGroups', N'Assignment groups', N'مجموعات الإسناد', N'The five IT sections that work tickets (Service Desk, Infrastructure, Applications Support, Network, Information Security) with their group lead.'),
(N'IT-HELPDESK', N'Services', N'IT services', N'خدمات تقنية المعلومات', N'Business and technical services supported by IT (core banking, digital banking, finance, HR, email, network, ATMs, end-user devices, the self-service portal) with owning group and criticality.'),
(N'IT-HELPDESK', N'ConfigurationItems', N'Configuration items', N'عناصر التهيئة', N'The CMDB: servers, databases, application modules, branch WAN and backup links, switches, Wi-Fi, VPN, firewalls, printers, ATMs (2-4 per branch) and staff laptops and desktops, with service, location, owning group, assigned employee, asset tag, model and status.'),
(N'IT-HELPDESK', N'Categories', N'Ticket categories', N'تصنيفات التذاكر', N'Category and subcategory of incidents and requests with the default assignment group.'),
(N'IT-HELPDESK', N'SlaPolicies', N'SLA policies', N'سياسات مستوى الخدمة', N'Response and resolution targets: incidents by priority (P1 15 minutes / 4 hours around the clock; P2 30 minutes / 8 business hours; P3 4 business hours / 3 business days; P4 1 / 5 business days) and requests by catalogue target.'),
(N'IT-HELPDESK', N'BusinessHours', N'Business hours', N'ساعات العمل', N'One row per day of 2025 for each schedule: HO (Monday-Friday 08:00-16:30, closed on UAE public holidays) used by SLAs, and 24X7 used by P1 incidents.'),
(N'IT-HELPDESK', N'ServiceCatalogItems', N'Service catalogue', N'كتالوج الخدمات', N'What employees can request: new joiner setup, system access per system, access removal, password reset, laptop or peripheral, software, VPN, mailbox or distribution list; fulfilment group, approvals needed and target days.'),
(N'IT-HELPDESK', N'ServiceRequests', N'Service requests', N'طلبات الخدمة', N'Requests raised in 2025: catalogue item, requested-for and requested-by employee, the requested-for person''s department, section and location at logging time, system and role for access requests, channel, creator, assignment group and agent, priority, status, opened, approved, fulfilled and closed times, SLA due time and breach flag.'),
(N'IT-HELPDESK', N'RequestApprovals', N'Request approvals', N'موافقات الطلبات', N'Approval steps of requests: line manager, then the system owner''s department head for system access; approver, requested and decided times and decision (Approved, Rejected, Pending).'),
(N'IT-HELPDESK', N'RequestTasks', N'Request fulfilment tasks', N'مهام تنفيذ الطلبات', N'Fulfilment steps of each request with the IT group and agent who did them, start and completion times.'),
(N'IT-HELPDESK', N'Incidents', N'Incidents', N'الحوادث', N'Incidents of 2025 from users (Portal, Phone, Email) and monitoring: service, configuration item, category, impact, urgency, priority (P1-P4), reporter and their department, section and location, creator, channel, assignment group and agent, status, opened, responded, resolved and closed times with SLA due times and breach flag, resolution code, major-incident flag and parent incident.'),
(N'IT-HELPDESK', N'IncidentActivities', N'Incident activity log', N'سجل نشاط الحوادث', N'Every change on an incident in time order: creation, group and agent assignments and reassignments, status changes, work notes and links to a parent incident, each by a user at a time.'),
(N'IT-HELPDESK', N'vw_IncidentsLive', N'Incidents (live December)', N'الحوادث (ديسمبر مباشر)', N'The incidents opened in December 2025 with every date moved forward so that 31 December 2025 is today in Asia/Dubai; lets rolling-window Monitoring Rules find the planted cases whenever the sample is used. Analyses of 2025 use Incidents.');
INSERT INTO #ColumnDocs VALUES
(N'PERSONNEL', N'Employees', N'EmiratesIdNumber', N'Emirates ID', N'رقم الهوية الإماراتية', N'National identity number.', N'Restricted'),
(N'PERSONNEL', N'Employees', N'PassportNumber', N'Passport number', N'رقم جواز السفر', NULL, N'Restricted'),
