INSERT INTO #CustomRoles VALUES
(N'Employee', N'Employee self-service', N'الخدمة الذاتية للموظف', N'Own IT Help Desk requests and incidents (SELF). Every Wabi Bank user holds it.'),
(N'CyberSecurity', N'Cyber Security', N'الأمن السيبراني', N'Digital Banking sign-ins and devices, Personnel system users and access, IT access requests (all rows); receives the sign-in alerts.'),
(N'BranchManager', N'Branch Manager', N'مدير الفرع', N'Core Banking, Digital Banking and IT Help Desk rows of the manager''s own branch (DEPARTMENT), without Restricted columns.'),
(N'Teller', N'Teller', N'صرّاف', N'Own postings only (SELF, through the staff views of Core Banking).'),
(N'HROfficer', N'HR Officer', N'موظف الموارد البشرية', N'Personnel and Attendance, all rows, without Restricted columns.'),
(N'BudgetController', N'Budget Controller', N'مراقب الميزانية', N'Finance, all rows; Personnel structure and headcount tables. Restricted columns (vendor IBAN, Emirates ID, passport) withheld.'),
(N'ComplianceOfficer', N'Compliance and AML Officer', N'مسؤول الامتثال ومكافحة غسل الأموال', N'Core Banking and Digital Banking, all rows including KYC documents; no Personnel data. Receives the AML alerts.'),
(N'ServiceDeskManager', N'IT Service Desk Manager', N'مدير مكتب خدمات تقنية المعلومات', N'IT Help Desk, all rows; Personnel employee directory without Restricted columns; no banking or finance data.');
