    INSERT INTO #Rules VALUES
(N'Same digital profile, several devices in a day', N'A digital-banking username signed in from more than two devices within 24 hours (possible account takeover). For the Cyber Security team to review; nobody is blocked automatically.', N'Data', N'multi_device_same_account', N'W1001', N'High', N'Daily', 0, N'06:00', N'DIGITAL-BANKING', N'vw_SignInsLive', N'{"data":{"objectId":"{{object}}","timeColumnId":"{{col:SignInAt}}","windowHours":24,"groupByColumnIds":["{{col:Username}}"],"measure":{"aggregate":"count_distinct","columnId":"{{col:DeviceId}}"},"filters":[],"condition":{"operator":"gt","value":2},"comparison":"none","maxGroups":200}}', N'CyberSecurity'),
(N'Cash deposits of AED 55,000 or more in a day (individuals)', N'An individual customer''s cash deposits within 24 hours reach the AED 55,000 cash reporting threshold, often in several smaller deposits (possible structuring). For the AML team.', N'Data', N'amount_above_threshold', N'W1007', N'High', N'Daily', 0, N'06:30', N'CORE-BANKING', N'vw_TransactionsLive', N'{"data":{"objectId":"{{object}}","timeColumnId":"{{col:PostedAt}}","windowHours":24,"groupByColumnIds":["{{col:CIF}}"],"measure":{"aggregate":"sum","columnId":"{{col:Amount}}"},"filters":[{"columnId":"{{col:TransactionCode}}","operator":"eq","values":["CDP"]},{"columnId":"{{col:CustomerType}}","operator":"eq","values":["Individual"]}],"condition":{"operator":"gte","value":55000},"comparison":"none","maxGroups":200}}', N'ComplianceOfficer'),
(N'More than two returned cheques per account in 30 days', N'Cheques drawn on one account were returned more than twice in 30 days. For the AML team and the account''s branch to follow up.', N'Data', N'many_events_per_entity', N'W1007', N'Medium', N'Daily', 0, N'06:30', N'CORE-BANKING', N'vw_InwardChequesLive', N'{"data":{"objectId":"{{object}}","timeColumnId":"{{col:PresentedDate}}","windowHours":720,"groupByColumnIds":["{{col:AccountNumber}}"],"measure":{"aggregate":"count"},"filters":[{"columnId":"{{col:Status}}","operator":"eq","values":["Returned"]}],"condition":{"operator":"gt","value":2},"comparison":"none","maxGroups":200}}', N'ComplianceOfficer'),
(N'More than three incidents on one configuration item in 7 days', N'The same configuration item had more than three incidents within a week; consider a problem record.', N'Data', N'many_events_per_entity', N'W1008', N'Medium', N'Daily', 0, N'07:00', N'IT-HELPDESK', N'vw_IncidentsLive', N'{"data":{"objectId":"{{object}}","timeColumnId":"{{col:OpenedAt}}","windowHours":168,"groupByColumnIds":["{{col:CiCode}}"],"measure":{"aggregate":"count"},"filters":[{"columnId":"{{col:CiCode}}","operator":"not_null","values":[]}],"condition":{"operator":"gt","value":3},"comparison":"none","maxGroups":200}}', N'ServiceDeskManager'),
(N'KYC documents looked up outside Compliance', N'Someone outside the Compliance role read KYC documents (Restricted identity data) through Wabi Insight.', N'Access', NULL, N'W1001', N'High', N'Interval', 60, N'00:00', NULL, NULL, N'{"access":{"signal":"accesses","windowHours":24,"objectIds":["{{obj:CORE-BANKING/KycDocuments}}"],"roleCodes":["OrganizationAdmin","Management","Analyst","CyberSecurity","BranchManager","Teller","HROfficer","BudgetController","ServiceDeskManager","Employee"],"threshold":{"mode":"absolute","value":0.5}}}', N'ComplianceOfficer');
